func NewPluginsValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) PluginsValue {
	object, diags := NewPluginsValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewPluginsValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t PluginsType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewPluginsValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewPluginsValueUnknown(), nil
	}

	if in.IsNull() {
		return NewPluginsValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewPluginsValueMust(PluginsValue{}.AttributeTypes(ctx), attributes), nil
}

func (t PluginsType) ValueType(ctx context.Context) attr.Value {
	return PluginsValue{}
}

var _ basetypes.ObjectValuable = PluginsValue{}

type PluginsValue struct {
	Device     basetypes.BoolValue `tfsdk:"device"`
	Errors     basetypes.BoolValue `tfsdk:"errors"`
	Logs       basetypes.BoolValue `tfsdk:"logs"`
	PageEvents basetypes.BoolValue `tfsdk:"page_events"`
	RageClick  basetypes.BoolValue `tfsdk:"rage_click"`
	Replay     basetypes.BoolValue `tfsdk:"replay"`
	state      attr.ValueState
}

func (v PluginsValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 6)

	var val tftypes.Value
	var err error

	attrTypes["device"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["errors"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["logs"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["page_events"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["rage_click"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["replay"] = basetypes.BoolType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 6)

		val, err = v.Device.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["device"] = val

		val, err = v.Errors.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["errors"] = val

		val, err = v.Logs.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["logs"] = val

		val, err = v.PageEvents.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["page_events"] = val

		val, err = v.RageClick.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["rage_click"] = val

		val, err = v.Replay.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["replay"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v PluginsValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v PluginsValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v PluginsValue) String() string {
	return "PluginsValue"
}

func (v PluginsValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"device":      basetypes.BoolType{},
		"errors":      basetypes.BoolType{},
		"logs":        basetypes.BoolType{},
		"page_events": basetypes.BoolType{},
		"rage_click":  basetypes.BoolType{},
		"replay":      basetypes.BoolType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"device":      v.Device,
			"errors":      v.Errors,
			"logs":        v.Logs,
			"page_events": v.PageEvents,
			"rage_click":  v.RageClick,
			"replay":      v.Replay,
		})

	return objVal, diags
}

func (v PluginsValue) Equal(o attr.Value) bool {
	other, ok := o.(PluginsValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Device.Equal(other.Device) {
		return false
	}

	if !v.Errors.Equal(other.Errors) {
		return false
	}

	if !v.Logs.Equal(other.Logs) {
		return false
	}

	if !v.PageEvents.Equal(other.PageEvents) {
		return false
	}

	if !v.RageClick.Equal(other.RageClick) {
		return false
	}

	if !v.Replay.Equal(other.Replay) {
		return false
	}

	return true
}

